CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_department]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_department]
	(
		[apuk_accountid],
		[apuk_accountid_entitytype],
		[apuk_accountidname],
		[apuk_accountidyominame],
		[apuk_city],
		[apuk_countryid],
		[apuk_countryid_entitytype],
		[apuk_countryidname],
		[apuk_county],
		[apuk_departmentcode],
		[apuk_departmentid],
		[apuk_emailaddress],
		[apuk_name],
		[apuk_postcode],
		[apuk_street1],
		[apuk_street2],
		[apuk_street3],
		[apuk_telephone],
		[apuk_website],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_accountid],
		stg.[apuk_accountid_entitytype],
		stg.[apuk_accountidname],
		stg.[apuk_accountidyominame],
		stg.[apuk_city],
		stg.[apuk_countryid],
		stg.[apuk_countryid_entitytype],
		stg.[apuk_countryidname],
		stg.[apuk_county],
		stg.[apuk_departmentcode],
		stg.[apuk_departmentid],
		stg.[apuk_emailaddress],
		stg.[apuk_name],
		stg.[apuk_postcode],
		stg.[apuk_street1],
		stg.[apuk_street2],
		stg.[apuk_street3],
		stg.[apuk_telephone],
		stg.[apuk_website],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_department] stg
		LEFT JOIN [synapse_ce].[apuk_department] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
